  const typed = (value: unknown): string => value === undefined ? '\\SemioVizUndefined{}' : value === null ? '\\SemioVizNull{}' : typeof value === 'boolean' ? `\\SemioVizBoolean{${value}}` : typeof value === 'string' ? `\\SemioVizString{${value}}` : String(value);
