  const records = await compileVizProbeDocument({case:'native-chart-grammar',scenario:'directed-graph',documentClass:'semio',documentClassOptions:'type=paper,language=en',packages:['semio-viz'],geometry:true,preamble:['\\title{Directed Graph Grammar}','\\author{Semio}','\\date{}','\\errorcontextlines=200'],body:bodies},{workDir,scenario:undefined,keepWorkDir:true});
